import type {
  StorageBucket,
  StorageFeatureData,
  StorageFeaturePackProps,
  StorageObject
} from '../feature-packs/storage/storage-feature-pack';
import {
  executeConstructiveConnectionQuery,
  executeConstructiveGraphQL,
  selectExistingFields,
  type ConstructiveSchemaSnapshot
} from '../console-kit/constructive/constructive-graphql';
import { asBoolean, asRecord, asString } from '../console-kit/constructive/constructive-values';
import {
  scopeField,
  scopeMutation,
  scopeMutationDocument,
  scopeType,
  supportsScopeObject,
  type ScopeNames
} from './scope-names';
import { scopeEntityId, type ScopeRuntime, type ScopeSchemas, type ScopeTarget } from './scope-runtime';

/**
 * One scope's files on the app API: the buckets an entity (an organization,
 * a data room) owns and the current version of each file in one of them.
 * Uploads go through the storage plugin's `upload<Scope>File`, which signs a
 * PUT the browser sends straight to the object store.
 */
export type ScopeFilesView = Pick<StorageFeaturePackProps, 'resource' | 'policy' | 'actions'>;

type FileRow = Readonly<{ id: string; key: string; object: StorageObject }>;

/** The scope's storage on the app API, as the signed-in user reads it. */
type Storage = Readonly<{
  runtime: ScopeRuntime;
  data: ConstructiveSchemaSnapshot;
  names: ScopeNames;
  entityId?: string;
}>;

const HIDDEN_STATUSES = new Set(['rejected', 'expired']);

function sizeLabel(value: unknown): string | undefined {
  const bytes = typeof value === 'number' ? value : typeof value === 'string' ? Number(value) : NaN;
  if (!Number.isFinite(bytes)) return undefined;
  const units = ['B', 'KB', 'MB', 'GB'];
  let size = bytes;
  let unit = 0;
  while (size >= 1024 && unit < units.length - 1) {
    size /= 1024;
    unit += 1;
  }
  return `${unit === 0 ? size : size.toFixed(1)} ${units[unit]}`;
}

async function sha256Hex(file: Blob): Promise<string> {
  const digest = await globalThis.crypto.subtle.digest('SHA-256', await file.arrayBuffer());
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

async function readBuckets({ runtime, data, names, entityId }: Storage, signal: AbortSignal): Promise<StorageBucket[]> {
  const rows = await executeConstructiveConnectionQuery(runtime, 'data', {
    operationName: `ConsoleKit${names.pascal}Buckets`,
    fieldName: scopeField(names, 'Buckets'),
    nodeSelection: selectExistingFields(data, scopeType(names, 'Bucket'), ['id', 'key', 'isPublic', 'description']).join(' '),
    ...(entityId ? { equalTo: { ownerId: entityId } } : {})
  }, signal);
  return rows.flatMap((row) => {
    const id = asString(row.id);
    const key = asString(row.key);
    return id && key ? [{ id, key, name: key, access: asBoolean(row.isPublic) ? 'public' : 'private' }] : [];
  });
}

// Every page of the bucket's files, current versions only.
async function readFiles({ runtime, data, names }: Storage, bucketId: string, signal: AbortSignal): Promise<FileRow[]> {
  const rows = await executeConstructiveConnectionQuery(runtime, 'data', {
    operationName: `ConsoleKit${names.pascal}Files`,
    fieldName: scopeField(names, 'Files'),
    nodeSelection: selectExistingFields(data, scopeType(names, 'File'), [
      'id', 'key', 'filename', 'mimeType', 'size', 'status', 'updatedAt', 'isLatest'
    ]).join(' '),
    equalTo: { bucketId }
  }, signal);
  return rows.flatMap((row) => {
    const id = asString(row.id);
    const key = asString(row.key);
    if (!id || !key) return [];
    if (row.isLatest === false || HIDDEN_STATUSES.has(asString(row.status) ?? '')) return [];
    return [{
      id,
      key,
      object: {
        id,
        key,
        name: asString(row.filename) ?? key,
        kind: 'file',
        contentType: asString(row.mimeType) ?? undefined,
        sizeLabel: sizeLabel(row.size),
        updatedAt: asString(row.updatedAt) ?? undefined
      }
    }];
  });
}

// Signs one upload and sends the bytes; a file the bucket already holds isn't sent again.
async function uploadFile({ runtime, names, entityId }: Storage, bucketKey: string, file: File): Promise<void> {
  const result = await executeConstructiveGraphQL<Record<string, unknown>>(
    runtime,
    'data',
    scopeMutationDocument(names, 'upload', 'File', 'uploadUrl uploadHeaders deduplicated'),
    {
      input: {
        bucketKey,
        ...(entityId ? { ownerId: entityId } : {}),
        contentHash: await sha256Hex(file),
        contentType: file.type || 'application/octet-stream',
        size: file.size,
        filename: file.name
      }
    }
  );
  const payload = asRecord(result[scopeMutation(names, 'upload', 'File')]);
  if (asBoolean(payload?.deduplicated)) return;
  const url = asString(payload?.uploadUrl);
  if (!url) throw new Error(`${file.name} got no upload address.`);
  const headers = Object.fromEntries(
    Object.entries(asRecord(payload?.uploadHeaders) ?? {}).flatMap(([name, value]) =>
      typeof value === 'string' ? [[name, value]] : []
    )
  );
  const put = await fetch(url, { method: 'PUT', headers, body: file });
  if (!put.ok) throw new Error(`${file.name} could not be uploaded (${put.status}).`);
}

// An entity type a blueprint declares comes with its buckets; one made
// without any gets them here, when the API offers the scope's create and the
// user may (its RLS decides). A new bucket is the session user's.
function bucketCreator(
  { runtime, data, names, entityId }: Storage,
  onChange: (bucketKey?: string) => void
): NonNullable<ScopeFilesView['actions']>['createBucket'] {
  const accepts = (fields: readonly string[]) => supportsScopeObject(data, names, 'create', 'Bucket', fields);
  if (!accepts(['key', ...(entityId ? ['ownerId'] : [])])) return undefined;
  const actorId = runtime.session.status === 'authenticated' ? runtime.session.identity.subjectId : undefined;
  return async ({ name, access }) => {
    const bucket: Record<string, unknown> = { key: name, ...(entityId ? { ownerId: entityId } : {}) };
    if (actorId && accepts(['actorId'])) bucket.actorId = actorId;
    if (accepts(['isPublic'])) bucket.isPublic = access === 'public';
    await executeConstructiveGraphQL(runtime, 'data', scopeMutationDocument(names, 'create', 'Bucket'), {
      input: { [scopeField(names, 'Bucket')]: bucket }
    });
    onChange(name);
  };
}

/** Reads the files view of one scope's entity, with the actions its API allows. */
export async function loadScopeFiles(
  runtime: ScopeRuntime,
  schemas: ScopeSchemas,
  target: ScopeTarget,
  selectedBucketKey: string | undefined,
  onChange: (bucketKey?: string) => void,
  signal: AbortSignal
): Promise<ScopeFilesView> {
  const { names } = target;
  const data = schemas.data;
  if (!data?.queryFields[scopeField(names, 'Buckets')] || !data.queryFields[scopeField(names, 'Files')]) {
    return { resource: { status: 'empty' } };
  }
  const storage: Storage = { runtime, data, names, entityId: scopeEntityId(target) };
  const buckets = await readBuckets(storage, signal);
  const createBucket = bucketCreator(storage, onChange);
  if (buckets.length === 0) {
    return createBucket
      ? {
          resource: { status: 'ready', quality: 'authoritative', data: { buckets: [], objects: [] } },
          policy: { createBucket: true },
          actions: { createBucket }
        }
      : { resource: { status: 'empty' } };
  }

  const active = buckets.find((bucket) => bucket.key === selectedBucketKey) ?? buckets[0]!;
  const files = await readFiles(storage, active.id, signal);
  const fileByKey = new Map(files.map((file) => [file.key, file] as const));
  const known = (objectKey: string) => {
    const file = fileByKey.get(objectKey);
    if (!file) throw new Error('The requested file is not in the current authorized resource.');
    return file;
  };
  const canUpload = Boolean(data.mutationFields[scopeMutation(names, 'upload', 'File')]);
  const canDownload = Boolean(data.types[scopeType(names, 'File')]?.fields.some((field) => field.name === 'downloadUrl'));
  const canDelete = Boolean(data.mutationFields[scopeMutation(names, 'delete', 'File')]);

  // Every page of the open bucket's files is loaded, so its count is exact;
  // the other buckets' counts stay unknown until they are opened.
  const view: StorageFeatureData = {
    buckets: buckets.map((bucket) => (bucket === active ? { ...bucket, objectCount: files.length } : bucket)),
    activeBucketKey: active.key,
    objects: files.map((file) => file.object)
  };

  return {
    resource: { status: 'ready', quality: 'authoritative', data: view },
    policy: {
      selectBucket: buckets.length > 1,
      navigate: false,
      createBucket: Boolean(createBucket),
      upload: canUpload,
      download: canDownload,
      deleteObject: canDelete
    },
    actions: {
      createBucket,
      selectBucket: buckets.length > 1
        ? ({ bucketKey }) => {
            if (!buckets.some((bucket) => bucket.key === bucketKey)) {
              throw new Error('The requested bucket is not visible to this session.');
            }
            onChange(bucketKey);
          }
        : undefined,
      upload: canUpload
        ? async ({ files: chosen }) => {
            for (const file of chosen) await uploadFile(storage, active.key, file);
            onChange(active.key);
          }
        : undefined,
      download: canDownload
        ? async ({ objectKey }) => {
            const file = known(objectKey);
            const rows = await executeConstructiveConnectionQuery(runtime, 'data', {
              operationName: `ConsoleKit${names.pascal}FileDownload`,
              fieldName: scopeField(names, 'Files'),
              nodeSelection: 'id downloadUrl',
              equalTo: { id: file.id }
            });
            const url = asString(rows[0]?.downloadUrl);
            if (!url) throw new Error('This file has no download address for you yet.');
            globalThis.open?.(url, '_blank', 'noopener');
          }
        : undefined,
      deleteObject: canDelete
        ? async ({ objectKey }) => {
            await executeConstructiveGraphQL(
              runtime,
              'data',
              scopeMutationDocument(names, 'delete', 'File', 'clientMutationId'),
              { input: { id: known(objectKey).id } }
            );
            onChange(active.key);
          }
        : undefined
    }
  };
}

import * as React from 'react';

import {
  normalizeFeaturePackError,
  type FeaturePackResource
} from '../feature-packs/shared/feature-pack-contracts';

/** What a scope panel renders: its resource, and the policy and actions the load found. */
export type ScopeView<Data, Policy, Actions> = Readonly<{
  resource: FeaturePackResource<Data>;
  policy?: Policy;
  actions?: Actions;
}>;

/**
 * A scope panel's view, loaded again on `reload` and whenever `load` changes
 * (memoize it on what it reads). A failure becomes the panel's error state,
 * with a retry; a load the panel no longer needs is dropped.
 */
export function useScopeView<Data, Policy, Actions>(
  load: (signal: AbortSignal, reload: () => void) => Promise<ScopeView<Data, Policy, Actions>>,
  failureMessage: string
): ScopeView<Data, Policy, Actions> {
  const [version, setVersion] = React.useState(0);
  const [view, setView] = React.useState<ScopeView<Data, Policy, Actions>>({ resource: { status: 'loading' } });

  React.useEffect(() => {
    const controller = new AbortController();
    const reload = () => setVersion((current) => current + 1);
    load(controller.signal, reload)
      .then((next) => {
        if (!controller.signal.aborted) setView(next);
      })
      .catch((error: unknown) => {
        if (controller.signal.aborted) return;
        setView({
          resource: { status: 'error', error: normalizeFeaturePackError(error, failureMessage), retry: reload }
        });
      });
    return () => controller.abort();
  }, [load, failureMessage, version]);

  return view;
}

'use client';

import * as React from 'react';

import { createScopeRuntime, type ScopeHost, type ScopeRuntime } from './scope-runtime';

const ScopeRuntimeContext = React.createContext<ScopeRuntime | null>(null);

/**
 * Gives the scope blocks under it the app's endpoints and session. The
 * runtime changes only when an endpoint or the signed-in user does; the token
 * is read through the latest `getAccessToken` at each request.
 */
export function ScopeAccessProvider({
  host,
  children
}: Readonly<{ host: ScopeHost; children: React.ReactNode }>) {
  const tokenRef = React.useRef(host.getAccessToken);
  // The latest getter, kept after each commit rather than written during render.
  React.useLayoutEffect(() => {
    tokenRef.current = host.getAccessToken;
  });
  const { admin, auth, data, storage } = host.endpoints;
  const runtime = React.useMemo(
    () => createScopeRuntime({
      endpoints: { admin, auth, data, storage },
      userId: host.userId,
      getAccessToken: () => tokenRef.current(),
      ...(host.fetch ? { fetch: host.fetch } : {})
    }),
    [admin, auth, data, storage, host.userId, host.fetch]
  );
  return <ScopeRuntimeContext.Provider value={runtime}>{children}</ScopeRuntimeContext.Provider>;
}

export function useScopeRuntime(): ScopeRuntime {
  const runtime = React.useContext(ScopeRuntimeContext);
  if (!runtime) throw new Error('Scope blocks need a ScopeAccessProvider above them.');
  return runtime;
}

'use client';

import * as React from 'react';

import type { FeaturePackError } from '../feature-packs/shared/feature-pack-contracts';
import { UsersFeaturePack, type UsersSection } from '../feature-packs/users/users-feature-pack';
import { capitalized, type UsersScopeNoun } from '../feature-packs/users/users-scope-noun';
import { loadScopeAccess } from './scope-access-load';
import { useScopeRuntime } from './scope-access-provider';
import { scopeAccessView } from './scope-access-view';
import { scopeNames } from './scope-names';
import { loadScopeSchemas } from './scope-runtime';
import { useScopeView } from './use-scope-view';

export type ScopeAccessPanelProps = Readonly<{
  /** The membership scope, as `membershipTypes.scope` names it: `app`, `org`, `data_room`. */
  scope: string;
  /** The entity whose members to show; every scope but `app` needs one. */
  entityId?: string;
  title?: string;
  description?: string;
  noun?: UsersScopeNoun;
  section?: UsersSection;
  defaultSection?: UsersSection;
  onSectionChange?: (section: UsersSection) => void;
  onError?: (error: FeaturePackError) => void;
}>;

/**
 * One scope's members, invitations, profiles and capabilities, read and
 * changed as the signed-in user: the App access view on any scope. Every
 * action reloads it; RLS decides what the user sees and may do.
 */
export function ScopeAccessPanel({
  scope,
  entityId,
  title,
  description,
  noun,
  section,
  defaultSection,
  onSectionChange,
  onError
}: ScopeAccessPanelProps) {
  const runtime = useScopeRuntime();
  const names = React.useMemo(() => scopeNames(scope), [scope]);
  const load = React.useCallback(async (signal: AbortSignal, reload: () => void) => {
    const target = { names, entityId };
    const schemas = await loadScopeSchemas(runtime, ['admin', 'auth']);
    const directory = await loadScopeAccess(runtime, schemas, target, signal);
    return scopeAccessView(runtime, schemas, target, directory, reload);
  }, [runtime, names, entityId]);
  const state = useScopeView(load, `The ${names.noun.long} members could not be loaded.`);

  return (
    <UsersFeaturePack
      actions={state.actions}
      defaultSection={defaultSection}
      description={description}
      noun={noun ?? names.noun}
      onError={onError}
      onSectionChange={onSectionChange}
      policy={state.policy}
      resource={state.resource}
      section={section}
      title={title ?? (names.entity ? `${capitalized(names.noun.long)} access` : 'App access')}
    />
  );
}

'use client';

import * as React from 'react';
import { MailOpenIcon } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { SectionHeading } from '@/components/ui/workspace-kit/surface';

import { normalizeFeaturePackError, type FeaturePackError } from '../feature-packs/shared/feature-pack-contracts';
import { articled } from '../feature-packs/users/users-scope-noun';
import {
  acceptPendingInvite,
  loadPendingInvites,
  type PendingInvite
} from './pending-invites-load';
import { useScopeRuntime } from './scope-access-provider';
import { loadScopeSchemas } from './scope-runtime';

export type PendingInvitesProps = Readonly<{
  /** Names the entity an invitation admits to, when the app knows it. */
  entityLabel?: (invite: PendingInvite) => string | undefined;
  /** Runs after an invitation is accepted, so the app can show the new access. */
  onAccepted?: (invite: PendingInvite) => void;
  onError?: (error: FeaturePackError) => void;
  /** Shown when there is nothing to accept; nothing renders without it. */
  empty?: React.ReactNode;
}>;

function inviteText(invite: PendingInvite, label: string | undefined): string {
  const what = label ?? (invite.scope.entity ? articled(invite.scope.noun.long) : 'this application');
  return invite.senderName ? `${invite.senderName} invited you to ${what}.` : `You're invited to ${what}.`;
}

/**
 * The invitations waiting for the signed-in user in every membership scope:
 * the app, an organization, a data room. Accepting one adds the membership
 * the invitation grants, with no link to follow.
 */
export function PendingInvites({ entityLabel, onAccepted, onError, empty = null }: PendingInvitesProps) {
  const runtime = useScopeRuntime();
  const [invites, setInvites] = React.useState<readonly PendingInvite[] | null>(null);
  const [pending, setPending] = React.useState<string | null>(null);
  const [version, setVersion] = React.useState(0);
  // The host's handler may be a new function each render; it doesn't start a new load.
  const reportLoadError = React.useEffectEvent((error: unknown) => {
    onError?.(normalizeFeaturePackError(error, 'Your invitations could not be loaded.'));
  });

  React.useEffect(() => {
    const controller = new AbortController();
    loadScopeSchemas(runtime, ['admin', 'auth'])
      .then((schemas) => loadPendingInvites(runtime, schemas, controller.signal))
      .then((rows) => {
        if (!controller.signal.aborted) setInvites(rows);
      })
      .catch((error: unknown) => {
        if (controller.signal.aborted) return;
        setInvites([]);
        reportLoadError(error);
      });
    return () => controller.abort();
  }, [runtime, version]);

  if (!invites) return null;
  if (invites.length === 0) return <>{empty}</>;

  return (
    <section aria-label='Invitations for you' className='flex flex-col gap-3'>
      <SectionHeading title='Invitations for you' />
      <ul className='flex flex-col divide-y rounded-lg border'>
        {invites.map((invite) => (
          <li className='flex items-center gap-3 px-4 py-3' key={`${invite.scope.scope}:${invite.id}`}>
            <MailOpenIcon aria-hidden className='size-4 shrink-0 text-muted-foreground' />
            <span className='min-w-0 flex-1 text-sm'>{inviteText(invite, entityLabel?.(invite))}</span>
            <Button
              disabled={pending !== null}
              onClick={async () => {
                setPending(invite.id);
                try {
                  await acceptPendingInvite(runtime, invite);
                  onAccepted?.(invite);
                  setVersion((current) => current + 1);
                } catch (error) {
                  onError?.(normalizeFeaturePackError(error, 'The invitation could not be accepted.'));
                } finally {
                  setPending(null);
                }
              }}
              size='sm'
            >
              Accept
            </Button>
          </li>
        ))}
      </ul>
    </section>
  );
}

'use client';

import * as React from 'react';

import type { FeaturePackError } from '../feature-packs/shared/feature-pack-contracts';
import { StorageFeaturePack } from '../feature-packs/storage/storage-feature-pack';
import { useScopeRuntime } from './scope-access-provider';
import { loadScopeFiles } from './scope-files';
import { scopeNames } from './scope-names';
import { loadScopeSchemas } from './scope-runtime';
import { useScopeView } from './use-scope-view';

export type ScopeFilesPanelProps = Readonly<{
  /** The membership scope that owns the files: `org`, `data_room`, … */
  scope: string;
  /** The entity whose buckets to show; every scope but `app` needs one. */
  entityId?: string;
  onError?: (error: FeaturePackError) => void;
  className?: string;
}>;

/**
 * An entity's files (a data room's documents, an organization's attachments)
 * with upload, download and delete as the signed-in user. The backend's
 * capabilities and RLS decide which files show and which actions succeed.
 */
export function ScopeFilesPanel({ scope, entityId, onError, className }: ScopeFilesPanelProps) {
  const runtime = useScopeRuntime();
  const names = React.useMemo(() => scopeNames(scope), [scope]);
  const [bucketKey, setBucketKey] = React.useState<string | undefined>();
  const load = React.useCallback(async (signal: AbortSignal, reload: () => void) => {
    // A write opens the bucket it touched and reads it again.
    const onChange = (key?: string) => {
      setBucketKey(key);
      reload();
    };
    const schemas = await loadScopeSchemas(runtime, ['data']);
    return loadScopeFiles(runtime, schemas, { names, entityId }, bucketKey, onChange, signal);
  }, [runtime, names, entityId, bucketKey]);
  const view = useScopeView(load, `The ${names.noun.long} files could not be loaded.`);

  return (
    <StorageFeaturePack
      actions={view.actions}
      className={className}
      onError={onError}
      policy={view.policy}
      resource={view.resource}
    />
  );
}
